22	class StateDrain
23	{
24	public:
25	  using RD = ResumeDriver;
26	
27	  // scratch_gpa: the GUEST address of the V-register transport page (L26: the
28	  // mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the unset
29	  // sentinel; only the V dump sweep consults it. The simulator passes the real
30	  // value from platform.main_memory.
31	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
32	                      AndesCaps caps = AndesCaps::all())
33	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
34	  {}
35	
36	  // v5: declare whether the target engine has an L2 cache controller, and its
37	  // MMIO register base (dual of ResumeDriver::set_l2c). Off by default so an
38	  // engine without an L2C reads nothing back -- a load from an absent region
39	  // would fault the Program Buffer. The simulator calls this from its engine
40	  // config (has_shared_cache + NDS_L2C_REG_BASE).
41	  void set_l2c(bool present, uint64_t base)
42	  {
43	    l2c_present_ = present;
44	    l2c_base_    = base;
45	  }
46	
47	  // V2: attach a pure per-op event recorder (dual of
48	  // ResumeDriver::set_op_log); every drain read is recorded with its regno
49	  // and the value read back. Null (default) records nothing.
50	  void set_op_log(OpLog* log) { oplog_ = log; }
51	
52	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
53	  // drain_with_passthrough when the QEMU 1 snapshot is available.
54	  auto drain() -> hybrid_state_v1
