56	    hybrid_state_v1 state{};
57	    state.magic   = HYBRID_STATE_MAGIC;
58	    state.version = HYBRID_STATE_VERSION;
59	    state.flags   = HYBRID_FLAG_RV64;
60	    halt_and_capture_pc_priv(state);
61	
62	    for (uint16_t i = 1; i < 32; ++i)
63	      state.gpr[i] = read64(regno_gpr(i), "StateDrain GPR");
64	
65	    return state;
66	  }
67	
68	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
69	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
70	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
71	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set,
72	  // also freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
73	  // and vreg remain pass-through (read-only / too large for DM). L23 mscratch
74	  // and the L24 trap/interrupt CSRs round-trip too (ResumeDriver restores
75	  // them). The Andes block, the M-ext CSRs, and the writable L2C config
76	  // registers round-trip too.
77	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
78	  // contribution would otherwise be discarded as the passthrough preserves
79	  // QEMU1's pre-handoff value.
80	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
81	  {
82	    auto state = input;
83	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
84	
85	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
86	    // like the resume side -- the Program Buffer is reserved for state the
87	    // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
88	    // MMIO window).
89	    for (uint16_t i = 1; i < 32; ++i)
90	      state.gpr[i] = read64(regno_gpr(i), "StateDrain GPR");
91	
92	    if (input.flags & HYBRID_FLAG_FP) {
93	      for (uint16_t i = 0; i < 32; ++i)
94	        state.fpr[i] = read64(regno_fpr(i), "StateDrain FPR");
95	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
96	      state.fcsr = read64(regno_csr(RD::kCsrFcsr));
97	    }
98	
99	    if (input.flags & HYBRID_FLAG_V) {
100	      state.vstart = read64(regno_csr(RD::kCsrVstart));
101	      state.vxsat  = read64(regno_csr(RD::kCsrVxsat));
102	      state.vxrm   = read64(regno_csr(RD::kCsrVxrm));
103	      state.vcsr   = read64(regno_csr(RD::kCsrVcsr));
104	      state.vtype  = read64(regno_csr(RD::kCsrVtype));
105	      state.vl     = read64(regno_csr(RD::kCsrVl));
106	    }
107	
108	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
109	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
110	    // dropped and the stale QEMU1 value passes through into the drained state.
111	    state.mscratch = read64(regno_csr(RD::kCsrMscratch));
112	
113	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
114	    // restores them), so re-read them -- an in-ROI write must reach the drained
115	    // state instead of the stale QEMU1 passthrough value.
116	    state.mepc   = read64(regno_csr(RD::kCsrMepc));
117	    state.mcause = read64(regno_csr(RD::kCsrMcause));
118	    state.mtval  = read64(regno_csr(RD::kCsrMtval));
119	    state.mie    = read64(regno_csr(RD::kCsrMie));
120	    state.mip    = read64(regno_csr(RD::kCsrMip));
121	
122	    // S/U trap CSRs (ax66 registration, option A): ResumeDriver restores them
123	    // on S-mode-capable engines, so re-read them the same caps-gated way -- an
124	    // M-only engine keeps QEMU1's drained record as passthrough instead of
125	    // reading CSRs its RTL does not implement.
126	    if (caps_.supports_csr(RD::kCsrSatp))
127	      state.satp    = read64(regno_csr(RD::kCsrSatp));
128	    if (caps_.supports_csr(RD::kCsrMedeleg))
129	      state.medeleg = read64(regno_csr(RD::kCsrMedeleg));
130	    if (caps_.supports_csr(RD::kCsrMideleg))
131	      state.mideleg = read64(regno_csr(RD::kCsrMideleg));
132	
133	    state.mcycle   = read64(regno_csr(RD::kCsrMcycle));
134	    state.minstret = read64(regno_csr(RD::kCsrMinstret));
135	
136	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
137	    // in-ROI write reaches the drained state instead of the stale QEMU1
138	    // passthrough (same round-trip as mscratch). One caps-gated abstract read
139	    // per CSR. See drain_andes_m_ext.
140	    drain_andes_m_ext(state);
141	
142	    // v5: re-read the writable L2C config registers (the ones ResumeDriver
143	    // restored) so the --verify oracle sees the round-tripped values instead of
144	    // the stale QEMU1 passthrough. The ROI is trap-free and does not touch L2C
145	    // config, so these must match the producer. Clobbers x5/x6 -- safe here, the
146	    // GPRs are already captured above and the hart is terminal. See drain_l2c.
147	    drain_l2c(state);
148	
149	    // V data regfile: dump v0..v31 to the shared scratch region via the
150	    // Program Buffer LAST -- after every architectural read above -- so the
151	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
152	    // cannot corrupt the values already captured. The simulator's
153	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
154	    if (input.flags & HYBRID_FLAG_V)
155	      dump_v_to_scratch(input.vlenb);
156	
157	    return state;
158	  }
159	
160	  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
161	  // every other field through from the QEMU1 snapshot. Used when --verify is
162	  // off: the driver then consumes only the vsim mcycle delta, so the full
163	  // register-file readback drain_with_passthrough performs (~190 DMI abstract
164	  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
165	  // wasted wall-clock. The hart is left halted, identical to the full drain, so
166	  // the caller's file-write + exit path is unchanged.
167	  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
168	  {
169	    halt("StateDrain halt (minimal)");
170	
171	    auto state     = input;
172	    state.mcycle   = read64(regno_csr(RD::kCsrMcycle),
173	                                      "StateDrain mcycle");
174	    state.minstret = read64(regno_csr(RD::kCsrMinstret),
175	                                      "StateDrain minstret");
176	    return state;
177	  }
178	
179	private:
180	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
181	  // dmactive must transition 0->1 in its own write before haltreq is honored
182	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
183	  void halt(const char* ctx)
184	  {
185	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
186	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
187	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
188	  }
189	
190	  // Halt the hart and capture the two control fields every drain path needs:
191	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
192	  // blocks are filled by the caller, so drain() and drain_with_passthrough
193	  // share one halt + prologue.
194	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
195	  {
196	    halt("StateDrain halt");
197	    state.priv = read64(regno_csr(RD::kCsrDcsr),
198	                                  "StateDrain DCSR") & 0x3u;
199	    state.pc = read64(regno_csr(RD::kCsrDpc), "StateDrain DPC");
200	  }
201	
202	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
203	  // state. Abstract-only by design, same caps gate + canonical order as the
204	  // ResumeDriver restore.
205	  void drain_andes_m_ext(hybrid_state_v1& state)
206	  {
207	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
208	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
209	    if (!andes && !mext) return;
210	
211	    if (andes) {
212	#define X(field, addr, name) \
213	  if (caps_.supports_csr(addr)) \
214	    state.andes.field = read64(regno_csr(addr));
215	      HYBRID_ANDES_CSR_LIST(X)
216	#undef X
217	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
218	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
219	          state.andes.pmacfg[i] =
220	            read64(regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
221	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
222	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
223	          state.andes.pmaaddr[i] =
224	            read64(regno_csr(HYBRID_PMA_ADDR0_CSR + i));
225	    }
226	    if (mext) {
227	#define X(field, addr, name) \
228	  if (caps_.supports_csr(addr)) \
229	    state.m_ext.field = read64(regno_csr(addr));
230	      HYBRID_M_EXT_CSR_LIST(X)
231	#undef X
232	    }
233	  }
234	
235	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
236	  // L26: guards on the configured scratch GPA so a V drain never stores to a
237	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
238	  void dump_v_to_scratch(uint64_t vlenb)
239	  {
240	    if (scratch_gpa_ == kVScratchGpaUnset)
241	      throw std::runtime_error(
242	        "StateDrain: V state present but scratch GPA unset");
243	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
244	  }
245	
246	  // v5: re-read the writable L2C config registers via Program-Buffer word loads,
247	  // the dual of ResumeDriver::restore_l2c. Reads back ONLY the registers the
248	  // resume side restored -- Control, HPM Control, Way Allocation Masks -- so the
249	  // --verify oracle compares round-tripped values. Hard-gated on the engine
250	  // having an L2C (a load from an absent region faults the Program Buffer).
251	  void drain_l2c(hybrid_state_v1& state)
252	  {
253	    if (!(state.flags & HYBRID_FLAG_L2C)) return;
254	    if (!l2c_present_) return;
255	
256	    state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]  = pb_load_l2c_reg(HYBRID_L2C_OFF_CONTROL);
257	    state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8] = pb_load_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0);
258	    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
259	      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
260	      state.l2c.reg[off / 8] = pb_load_l2c_reg(off);
261	    }
262	  }
263	
264	  // One L2C register read-back: stage the MMIO address in x6, execute
265	  // `lwu x5, 0(x6)` in the Program Buffer, then read x5. lwu (zero-extend) so a
266	  // 32-bit register value does not sign-pollute the drained u64. Word access
267	  // per DS220 11.8.3 (< 8 bytes).
268	  auto pb_load_l2c_reg(uint32_t offset) -> uint64_t
269	  {
270	    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
271	    const std::array<uint32_t, 1> pb = { encode_lwu(5, 6, 0) };
272	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
273	    return read64(regno_gpr(5), "StateDrain L2C reg");
274	  }
275	
276	  // Recorded read: every architectural read funnels through here so an
277	  // attached OpLog sees (regno, value) per op.
278	  auto read64(uint16_t regno, const char* label = "read_register_64")
279	    -> uint64_t
280	  {
281	    const uint64_t v = read_register_64(bus_, regno, label);
282	    if (oplog_) oplog_->record(OpLog::Kind::AbstractRead, regno, v);
283	    return v;
284	  }
285	
286	  DmiBus& bus_;
287	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
288	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
289	  bool l2c_present_     = false;              // v5: engine has an L2C (set_l2c)
290	  uint64_t l2c_base_    = 0;                  // v5: L2C MMIO register base
291	  OpLog* oplog_ = nullptr;                    // V2: optional per-op recorder
292	};
293	
294	}  // namespace hybrid
295

file.content:
// StateDrain halts the hart via the Debug Module and populates a
// hybrid_state_v1 with the architectural register file. Reuses
// ResumeDriver's DM register constants and DmiBus interface.

#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/andes_caps.hpp"
#include "hybrid/dmi_poll.hpp"
#include "hybrid/op_log.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/v_regfile_xfer.hpp"

#include <array>
#include <cstdint>
#include <span>

namespace hybrid
{

class StateDrain
{
public:
  using RD = ResumeDriver;

  // scratch_gpa: the GUEST address of the V-register transport page (L26: the
  // mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the unset
  // sentinel; only the V dump sweep consults it. The simulator passes the real
  // value from platform.main_memory.
  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
                      AndesCaps caps = AndesCaps::all())
      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
  {}

  // v5: declare whether the target engine has an L2 cache controller, and its
  // MMIO register base (dual of ResumeDriver::set_l2c). Off by default so an
  // engine without an L2C reads nothing back -- a load from an absent region
  // would fault the Program Buffer. The simulator calls this from its engine
  // config (has_shared_cache + NDS_L2C_REG_BASE).
  void set_l2c(bool present, uint64_t base)
  {
    l2c_present_ = present;
    l2c_base_    = base;
  }

  // V2: attach a pure per-op event recorder (dual of
  // ResumeDriver::set_op_log); every drain read is recorded with its regno
  // and the value read back. Null (default) records nothing.
  void set_op_log(OpLog* log) { oplog_ = log; }

  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
  // drain_with_passthrough when the QEMU 1 snapshot is available.
  auto drain() -> hybrid_state_v1
  {
    hybrid_state_v1 state{};
    state.magic   = HYBRID_STATE_MAGIC;
    state.version = HYBRID_STATE_VERSION;
    state.flags   = HYBRID_FLAG_RV64;
    halt_and_capture_pc_priv(state);

    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read64(regno_gpr(i), "StateDrain GPR");

    return state;
  }

  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
  // (L20) so post-vsim FP modifications are captured (otherwise the stale
  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set,
  // also freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
  // and vreg remain pass-through (read-only / too large for DM). L23 mscratch
  // and the L24 trap/interrupt CSRs round-trip too (ResumeDriver restores
  // them). The Andes block, the M-ext CSRs, and the writable L2C config
  // registers round-trip too.
  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
  // contribution would otherwise be discarded as the passthrough preserves
  // QEMU1's pre-handoff value.
  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    auto state = input;
    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt

    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
    // like the resume side -- the Program Buffer is reserved for state the
    // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
    // MMIO window).
    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read64(regno_gpr(i), "StateDrain GPR");

    if (input.flags & HYBRID_FLAG_FP) {
      for (uint16_t i = 0; i < 32; ++i)
        state.fpr[i] = read64(regno_fpr(i), "StateDrain FPR");
      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
      state.fcsr = read64(regno_csr(RD::kCsrFcsr));
    }

    if (input.flags & HYBRID_FLAG_V) {
      state.vstart = read64(regno_csr(RD::kCsrVstart));
      state.vxsat  = read64(regno_csr(RD::kCsrVxsat));
      state.vxrm   = read64(regno_csr(RD::kCsrVxrm));
      state.vcsr   = read64(regno_csr(RD::kCsrVcsr));
      state.vtype  = read64(regno_csr(RD::kCsrVtype));
      state.vl     = read64(regno_csr(RD::kCsrVl));
    }

    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
    // dropped and the stale QEMU1 value passes through into the drained state.
    state.mscratch = read64(regno_csr(RD::kCsrMscratch));

    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
    // restores them), so re-read them -- an in-ROI write must reach the drained
    // state instead of the stale QEMU1 passthrough value.
    state.mepc   = read64(regno_csr(RD::kCsrMepc));
    state.mcause = read64(regno_csr(RD::kCsrMcause));
    state.mtval  = read64(regno_csr(RD::kCsrMtval));
    state.mie    = read64(regno_csr(RD::kCsrMie));
    state.mip    = read64(regno_csr(RD::kCsrMip));

    // S/U trap CSRs (ax66 registration, option A): ResumeDriver restores them
    // on S-mode-capable engines, so re-read them the same caps-gated way -- an
    // M-only engine keeps QEMU1's drained record as passthrough instead of
    // reading CSRs its RTL does not implement.
    if (caps_.supports_csr(RD::kCsrSatp))
      state.satp    = read64(regno_csr(RD::kCsrSatp));
    if (caps_.supports_csr(RD::kCsrMedeleg))
      state.medeleg = read64(regno_csr(RD::kCsrMedeleg));
    if (caps_.supports_csr(RD::kCsrMideleg))
      state.mideleg = read64(regno_csr(RD::kCsrMideleg));

    state.mcycle   = read64(regno_csr(RD::kCsrMcycle));
    state.minstret = read64(regno_csr(RD::kCsrMinstret));

    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
    // in-ROI write reaches the drained state instead of the stale QEMU1
    // passthrough (same round-trip as mscratch). One caps-gated abstract read
    // per CSR. See drain_andes_m_ext.
    drain_andes_m_ext(state);

    // v5: re-read the writable L2C config registers (the ones ResumeDriver
    // restored) so the --verify oracle sees the round-tripped values instead of
    // the stale QEMU1 passthrough. The ROI is trap-free and does not touch L2C
    // config, so these must match the producer. Clobbers x5/x6 -- safe here, the
    // GPRs are already captured above and the hart is terminal. See drain_l2c.
    drain_l2c(state);

    // V data regfile: dump v0..v31 to the shared scratch region via the
    // Program Buffer LAST -- after every architectural read above -- so the
    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
    // cannot corrupt the values already captured. The simulator's
    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
    if (input.flags & HYBRID_FLAG_V)
      dump_v_to_scratch(input.vlenb);

    return state;
  }

  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
  // every other field through from the QEMU1 snapshot. Used when --verify is
  // off: the driver then consumes only the vsim mcycle delta, so the full
  // register-file readback drain_with_passthrough performs (~190 DMI abstract
  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
  // wasted wall-clock. The hart is left halted, identical to the full drain, so
  // the caller's file-write + exit path is unchanged.
  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    halt("StateDrain halt (minimal)");

    auto state     = input;
    state.mcycle   = read64(regno_csr(RD::kCsrMcycle),
                                      "StateDrain mcycle");
    state.minstret = read64(regno_csr(RD::kCsrMinstret),
                                      "StateDrain minstret");
    return state;
  }

private:
  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
  // dmactive must transition 0->1 in its own write before haltreq is honored
  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
  void halt(const char* ctx)
  {
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
  }

  // Halt the hart and capture the two control fields every drain path needs:
  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
  // blocks are filled by the caller, so drain() and drain_with_passthrough
  // share one halt + prologue.
  void halt_and_capture_pc_priv(hybrid_state_v1& state)
  {
    halt("StateDrain halt");
    state.priv = read64(regno_csr(RD::kCsrDcsr),
                                  "StateDrain DCSR") & 0x3u;
    state.pc = read64(regno_csr(RD::kCsrDpc), "StateDrain DPC");
  }

  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
  // state. Abstract-only by design, same caps gate + canonical order as the
  // ResumeDriver restore.
  void drain_andes_m_ext(hybrid_state_v1& state)
  {
    const bool andes = state.flags & HYBRID_FLAG_ANDES;
    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    if (andes) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.andes.field = read64(regno_csr(addr));
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          state.andes.pmacfg[i] =
            read64(regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          state.andes.pmaaddr[i] =
            read64(regno_csr(HYBRID_PMA_ADDR0_CSR + i));
    }
    if (mext) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.m_ext.field = read64(regno_csr(addr));
      HYBRID_M_EXT_CSR_LIST(X)
#undef X
    }
  }

  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
  // L26: guards on the configured scratch GPA so a V drain never stores to a
  // bogus address (mirror of ResumeDriver's reload-sweep guard).
  void dump_v_to_scratch(uint64_t vlenb)
  {
    if (scratch_gpa_ == kVScratchGpaUnset)
      throw std::runtime_error(
        "StateDrain: V state present but scratch GPA unset");
    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
  }

  // v5: re-read the writable L2C config registers via Program-Buffer word loads,
  // the dual of ResumeDriver::restore_l2c. Reads back ONLY the registers the
  // resume side restored -- Control, HPM Control, Way Allocation Masks -- so the
  // --verify oracle compares round-tripped values. Hard-gated on the engine
  // having an L2C (a load from an absent region faults the Program Buffer).
  void drain_l2c(hybrid_state_v1& state)
  {
    if (!(state.flags & HYBRID_FLAG_L2C)) return;
    if (!l2c_present_) return;

    state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]  = pb_load_l2c_reg(HYBRID_L2C_OFF_CONTROL);
    state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8] = pb_load_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0);
    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
      state.l2c.reg[off / 8] = pb_load_l2c_reg(off);
    }
  }

  // One L2C register read-back: stage the MMIO address in x6, execute
  // `lwu x5, 0(x6)` in the Program Buffer, then read x5. lwu (zero-extend) so a
  // 32-bit register value does not sign-pollute the drained u64. Word access
  // per DS220 11.8.3 (< 8 bytes).
  auto pb_load_l2c_reg(uint32_t offset) -> uint64_t
  {
    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
    const std::array<uint32_t, 1> pb = { encode_lwu(5, 6, 0) };
    exec_progbuf(bus_, std::span<const uint32_t>{pb});
    return read64(regno_gpr(5), "StateDrain L2C reg");
  }

  // Recorded read: every architectural read funnels through here so an
  // attached OpLog sees (regno, value) per op.
  auto read64(uint16_t regno, const char* label = "read_register_64")
    -> uint64_t
  {
    const uint64_t v = read_register_64(bus_, regno, label);
    if (oplog_) oplog_->record(OpLog::Kind::AbstractRead, regno, v);
    return v;
  }

  DmiBus& bus_;
  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
  bool l2c_present_     = false;              // v5: engine has an L2C (set_l2c)
  uint64_t l2c_base_    = 0;                  // v5: L2C MMIO register base
  OpLog* oplog_ = nullptr;                    // V2: optional per-op recorder
};

}  // namespace hybrid

