1	// QEMU TCG plugin: drains architectural state and exits when the guest
2	// executes the ROI enter marker `slti x0, x0, 0x5A0` (a HINT NOP). Shares
3	// hybrid/insn_match.h and hybrid/state_abi.h with the vsim side.
4	
5	#include "hybrid/handoff_site.h"
6	#include "hybrid/insn_match.h"
7	#include "hybrid/reg_names.h"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_drain_policy.h"
10	#include "hybrid/write_mask.h"
11	
12	#include <qemu-plugin.h>
13	
14	#include <glib.h>
15	
16	#include <inttypes.h>
17	#include <stddef.h>
18	#include <stdint.h>
19	#include <stdio.h>
20	#include <stdlib.h>
21	#include <string.h>
22	#include <unistd.h>
23	#include <limits.h>
24	
25	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
26	
27	// Plugin-local X-macro lists for the CSRs where the VcpuRegs handle field,
28	// the gdb lookup string, and the hybrid_state_v1 field are the same token:
29	// one line per CSR generates all three consumers (handle field, resolve,
30	// drain), the same pattern the shared HYBRID_ANDES_CSR_LIST /
31	// HYBRID_M_EXT_CSR_LIST already use. The ABI struct keeps plain fields;
32	// list order is the existing drain order.
33	
34	// Base M-mode CSRs as exposed by QEMU's gdbstub csr feature.
35	#define HANDOFF_BASE_CSR_LIST(X) \
36	    X(mstatus) X(mepc) X(mtvec) X(mcause) X(mtval) X(mscratch) \
37	    X(medeleg) X(mideleg) X(mip) X(mie) X(mcycle) X(minstret) X(satp)
38	
39	// Andes custom machine setup CSRs (crt0 writes these at boot). mcache_ctl
40	// enables the L1 caches; without transporting it the cycle engine resumes
41	// with caches off. Absent on non-Andes stubs -> NULL handle -> drains 0.
42	#define HANDOFF_ANDES_SETUP_CSR_LIST(X) X(mcache_ctl) X(mmisc_ctl)
43	
44	// V scalar CSRs. vlenb stays in the list: s.vlenb feeds the V drain policy.
45	#define HANDOFF_V_CSR_LIST(X) \
46	    X(vstart) X(vxsat) X(vxrm) X(vcsr) X(vtype) X(vl) X(vlenb)
47	
48	typedef struct {
49	    struct qemu_plugin_register *gpr[32];
50	    struct qemu_plugin_register *fpr[32];
51	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
52	    struct qemu_plugin_register *pc;
53	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
54	
55	    // Base M-mode CSRs + the Andes machine-setup pair (see the shared
56	    // X-macro lists above).
57	#define HANDOFF_CSR_FIELD(csr) struct qemu_plugin_register *csr;
58	    HANDOFF_BASE_CSR_LIST(HANDOFF_CSR_FIELD)
59	    HANDOFF_ANDES_SETUP_CSR_LIST(HANDOFF_CSR_FIELD)
60	#undef HANDOFF_CSR_FIELD
61	
62	    // Andes V5 CSR block (v3). HYBRID_ANDES_CSR_LIST is the shared source of
63	    // truth; a NULL handle (non-Andes stub) drains 0 -> tolerant no-op.
64	#define HYBRID_ANDES_FIELD(field, addr, name) \
65	    struct qemu_plugin_register *andes_##field;
66	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
67	#undef HYBRID_ANDES_FIELD
68	    struct qemu_plugin_register *pmacfg[HYBRID_PMA_CFG_NUM];
69	    struct qemu_plugin_register *pmaaddr[HYBRID_PMA_ADDR_NUM];
70	
71	    // M-ext CSR block (v4). Same shared X-macro; a NULL handle (the stub's
72	    // gdbstub does not advertise this CSR for the paired cpu) drains 0.
73	#define HYBRID_M_EXT_FIELD(field, addr, name) \
74	    struct qemu_plugin_register *m_ext_##field;
75	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
76	#undef HYBRID_M_EXT_FIELD
77	
78	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
79	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
80	
81	#define HANDOFF_CSR_FIELD(csr) struct qemu_plugin_register *csr;
82	    HANDOFF_V_CSR_LIST(HANDOFF_CSR_FIELD)
83	#undef HANDOFF_CSR_FIELD
84	    struct qemu_plugin_register *vreg[32];
85	} VcpuRegs;
86	
87	static struct qemu_plugin_scoreboard *vcpu_state;
88	static char *outfile_path;
89	
90	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
91	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
92	// drain callback is registered only for instructions whose vaddr equals
93	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
94	// (entry into vsim), matching marker-mode enter-marker semantics.
95	static uint64_t enter_pc_arg;
96	static int pc_mode;
97	
98	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
99	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
100	// pure-QEMU run produces the differential verifier's reference state. Every
101	// insn gets an exec callback: the tick ARMS on the
102	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
103	// the next callback. Exec callbacks fire before their insn executes, so the
104	// armed drain captures "after the boundary insn retired" -- exactly vsim's
105	// exit-drain record (DPC = next insn to execute) -- and reports that next
106	// insn's vaddr as pc, correct even when the boundary insn branches.
107	// Exclusive with the other trigger modes: the oracle run never hands off.
108	//
109	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
110	// vaddr equals drain_pc, instead of the very next tick. The differential
111	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
112	// variable 0-3 insns past the trigger (the core keeps retiring while the
113	// haltreq propagates), and the two states only compare equal when both
114	// sides sample the SAME architectural point. If vsim's pc is never reached
115	// (a real control-flow divergence), the oracle never drains and QEMU runs
116	// to completion -- the caller sees exit != 200.
117	static uint64_t exit_pc_arg;
118	static int      exit_pc_mode;
119	static int      exit_marker_mode;
120	static uint64_t drain_pc_arg;
121	static int      drain_pc_set;
122	// v5: L2C MMIO register base. DS220 24.2 maps the AE350 L2C block at 0xE0500000;
123	// overridable via `l2c_base=0x...` for a platform with a relocated block.
124	static uint64_t l2c_base_arg = 0xE0500000ull;
125	
126	// LM transport (F1): hart-0 local-memory slave-port windows (AE350 memmap).
127	// When ilm_size/dlm_size/hvm_size are non-zero the drain also captures that
128	// many bytes of ILM/DLM/HVM CONTENT into raw sidecar files
129	// "<outfile>.ilm"/".dlm"/".hvm", for the vsim leg's --ilm/--dlm/--hvm
130	// backdoor load. The LM slave-port aperture is used (never the hart-local
131	// view: its ILM base 0x0 is also DRAM 0x0); HVM has only the one aperture
132	// (plain RAM at hvm_base, no enable bit). Size 0 (the default) = the paired
133	// engine has no such memory -> nothing read, no file written.
134	static uint64_t ilm_base_arg = 0xA0000000ull;
135	static uint64_t dlm_base_arg = 0xA0200000ull;
136	static uint64_t hvm_base_arg = 0x90000000ull;
137	static uint64_t ilm_size_arg;
138	static uint64_t dlm_size_arg;
139	static uint64_t hvm_size_arg;
140	
141	// Forwarded driver verbosity (plugin arg `log_level=N`, vsim's spdlog scale:
142	// 0=trace 1=debug 2=info ... 6=off). Chatter prints only at <= debug.
143	static uint64_t log_level_arg = 2;
144	static volatile int oracle_armed;
145	
146	// v6: which mask-governed config CSRs the guest has WRITTEN so far
147	// (hybrid/write_mask.h slot numbering). Marked by per-insn exec callbacks that
148	// are registered ONLY on instructions whose translate-time decode says "writes
149	// a governed CSR" -- steady-state code carries no instrumentation. Single-hart
150	// flow (like the rest of the handoff); atomics keep a future SMP guest safe.
151	static uint64_t csr_write_mask[2];
152	
153	static void on_csr_write(unsigned int vcpu_idx, void *udata)
154	{
155	    (void) vcpu_idx;
156	    const unsigned slot = (unsigned) (uintptr_t) udata;
157	    __atomic_fetch_or(&csr_write_mask[slot >> 6],
158	                      (uint64_t) 1 << (slot & 63u), __ATOMIC_RELAXED);
159	}
160	
161	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
162	{
163	    for (guint i = 0; i < regs->len; i++) {
164	        qemu_plugin_reg_descriptor *rd =
165	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
166	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
167	            return rd->handle;
168	        }
169	    }
170	    return NULL;
171	}
172	
173	// Lazily resolves register handles. The plugin's vcpu_init runs before
174	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
175	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
176	// regs at that moment. By the time the entry trigger fires, all dynamic
177	// features are registered and a fresh call returns the full list.
178	static void resolve_handles(VcpuRegs *v)
179	{
180	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
181	    for (int i = 0; i < 32; i++) {
182	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
183	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
184	    }
185	    v->fcsr = find_reg(regs, "fcsr");
186	    v->pc = find_reg(regs, "pc");
187	    v->priv = find_reg(regs, "priv");
188	
189	#define HANDOFF_CSR_RESOLVE(csr) v->csr = find_reg(regs, #csr);
190	    HANDOFF_BASE_CSR_LIST(HANDOFF_CSR_RESOLVE)
191	    HANDOFF_ANDES_SETUP_CSR_LIST(HANDOFF_CSR_RESOLVE)
192	#undef HANDOFF_CSR_RESOLVE
193	
194	    char buf[16];
195	
196	    // Andes V5 CSR block (v3): resolve by gdb mnemonic from the shared X-macro.
197	#define HYBRID_ANDES_FIELD(field, addr, name) v->andes_##field = find_reg(regs, name);
198	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
199	#undef HYBRID_ANDES_FIELD
200	
201	    // M-ext CSR block (v4): resolve by gdb mnemonic (NULL if the stub does not
202	    // advertise it for the paired cpu).
203	#define HYBRID_M_EXT_FIELD(field, addr, name) v->m_ext_##field = find_reg(regs, name);
204	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
205	#undef HYBRID_M_EXT_FIELD
206	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
207	        // RV64 packs 8 PMA entries per cfg CSR, so only even cfg CSRs exist.
208	        g_snprintf(buf, sizeof(buf), "pmacfg%d", 2 * i);
209	        v->pmacfg[i] = find_reg(regs, buf);
210	    }
211	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
212	        g_snprintf(buf, sizeof(buf), "pmaaddr%d", i);
213	        v->pmaaddr[i] = find_reg(regs, buf);
214	    }
215	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
216	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
217	        v->pmpcfg[i] = find_reg(regs, buf);
218	    }
219	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
220	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
221	        v->pmpaddr[i] = find_reg(regs, buf);
222	    }
223	
224	#define HANDOFF_CSR_RESOLVE(csr) v->csr = find_reg(regs, #csr);
225	    HANDOFF_V_CSR_LIST(HANDOFF_CSR_RESOLVE)
226	#undef HANDOFF_CSR_RESOLVE
227	    for (int i = 0; i < 32; i++) {
228	        g_snprintf(buf, sizeof(buf), "v%d", i);
229	        v->vreg[i] = find_reg(regs, buf);
230	    }
231	}
232	
233	static uint64_t read_reg64(struct qemu_plugin_register *h)
234	{
235	    if (!h) return 0;
236	    g_autoptr(GByteArray) buf = g_byte_array_new();
237	    int sz = qemu_plugin_read_register(h, buf);
238	    if (sz <= 0) return 0;
239	    uint64_t v = 0;
240	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
241	    return v;
242	}
243	
244	// Reads up to `dst_max` bytes from a register handle. Returns the byte
245	// count written (0 on failure or NULL handle). Used for vector regs whose
246	// width = vlenb bytes.
247	static size_t read_reg_bytes(struct qemu_plugin_register *h,
248	                             uint8_t *dst, size_t dst_max)
249	{
250	    if (!h || dst_max == 0) return 0;
251	    g_autoptr(GByteArray) buf = g_byte_array_new();
252	    int sz = qemu_plugin_read_register(h, buf);
253	    if (sz <= 0) return 0;
254	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
255	    memcpy(dst, buf->data, n);
256	    return n;
257	}
258	
259	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
260	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
261	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
262	// collide even under aggressive PID reuse (B13). The tmp lives in the
263	// same directory as `path` so the rename is intra-filesystem.
264	static int write_blob_atomic(const void *data, size_t len, const char *path)
265	{
266	    char tmp[PATH_MAX];
267	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
268	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
269	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
270	        return -1;
271	    }
272	    int fd = g_mkstemp(tmp);
273	    if (fd < 0) {
274	        perror("hybrid_handoff: g_mkstemp");
275	        return -1;
276	    }
277	    // g_mkstemp creates the file 0600; no further chmod needed.
278	    ssize_t got = write(fd, data, len);
279	    if (got != (ssize_t) len) {
280	        perror("hybrid_handoff: write");
281	        close(fd);
282	        unlink(tmp);
283	        return -1;
284	    }
285	    fsync(fd);
286	    close(fd);
287	    if (rename(tmp, path) != 0) {
288	        perror("hybrid_handoff: rename");
289	        unlink(tmp);
290	        return -1;
291	    }
292	    return 0;
293	}
294	
295	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
296	{
297	    return write_blob_atomic(s, sizeof(*s), path);
298	}
299	
300	// Drain CPU state into `*s`. pc is computed by the caller (from a
301	// HandoffSite for trigger paths).
302	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
303	                             struct hybrid_state_v1 *sp)
304	{
305	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
306	    resolve_handles(v);
307	    // hybrid_state_v1 is padding-free (state_abi_check.h pins every offset and
308	    // the total size), so the {0} local plus the field assignments below
309	    // determine every byte of *sp via the unconditional copy-out at the end.
310	    struct hybrid_state_v1 s = {0};
311	    s.magic   = HYBRID_STATE_MAGIC;
312	    s.version = HYBRID_STATE_VERSION;
313	    s.flags   = HYBRID_FLAG_RV64;
314	    s.hart_id = vcpu_idx;
315	    // L6: real privilege at the boundary; M-mode fallback only when the
316	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
317	    // reads as 0 = U, which would silently demote the hart).
318	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
319	    s.pc      = pc;
320	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
321	
322	    // Floating-point: only set FP flag if at least one handle was bound,
323	    // i.e. QEMU advertised the FPU feature (D extension).
324	    int has_fp = 0;
325	    for (int i = 0; i < 32; i++) {
326	        s.fpr[i] = read_reg64(v->fpr[i]);
327	        if (v->fpr[i]) has_fp = 1;
328	    }
329	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
330	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
331	
332	    // Base M-mode CSRs, then the Andes cache fix: carry crt0's cache-enable
333	    // so the cycle engine resumes with caches on (NULL handle on a non-Andes
334	    // stub reads back as 0).
335	#define HANDOFF_CSR_DRAIN(csr) s.csr = read_reg64(v->csr);
336	    HANDOFF_BASE_CSR_LIST(HANDOFF_CSR_DRAIN)
337	    HANDOFF_ANDES_SETUP_CSR_LIST(HANDOFF_CSR_DRAIN)
338	#undef HANDOFF_CSR_DRAIN
339	
340	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
341	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
342	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
343	    // handle on a non-Andes stub reads back as 0 -> tolerant.
344	    int has_andes = 0;
345	#define HYBRID_ANDES_FIELD(field, addr, name)  \
346	    s.andes.field = read_reg64(v->andes_##field); \
347	    if (v->andes_##field) has_andes = 1;
348	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
349	#undef HYBRID_ANDES_FIELD
350	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
351	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
352	        if (v->pmacfg[i]) has_andes = 1;
353	    }
354	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
355	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
356	        if (v->pmaaddr[i]) has_andes = 1;
357	    }
358	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
359	
360	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
361	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
362	    // reads 0. The vsim caps gate decides which of these the cycle engine
363	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
364	    int has_m_ext = 0;
365	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
366	    s.m_ext.field = read_reg64(v->m_ext_##field); \
367	    if (v->m_ext_##field) has_m_ext = 1;
368	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
369	#undef HYBRID_M_EXT_FIELD
370	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
371	
372	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
373	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
374	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
375	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
376	
377	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
378	    // bounds the per-register byte count copied into vreg[]. The policy
379	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
380	    // handle truthiness so we don't conflate "stub missing vlenb" with
381	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
382	#define HANDOFF_CSR_DRAIN(csr) s.csr = read_reg64(v->csr);
383	    HANDOFF_V_CSR_LIST(HANDOFF_CSR_DRAIN)
384	#undef HANDOFF_CSR_DRAIN
385	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
386	                       || v->vtype || v->vl);
387	    if (!has_other_v) {
388	        for (int i = 0; i < 32; i++)
389	            if (v->vreg[i]) { has_other_v = 1; break; }
390	    }
391	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
392	        v->vlenb != NULL, has_other_v, s.vlenb);
393	    if (vpol == HYBRID_V_DRAIN_ABORT) {
394	        if (v->vlenb == NULL)
395	            fprintf(stderr,
396	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
397	                    "vlenb; refusing to drain partial V state\n");
398	        else
399	            fprintf(stderr,
400	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
401	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
402	                    "truncate V registers\n",
403	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
404	                    8 * HYBRID_VLEN_BYTES_MAX);
405	        exit(2);
406	    }
407	    if (vpol == HYBRID_V_DRAIN_OK) {
408	        s.flags |= HYBRID_FLAG_V;
409	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
410	         * full live register fits the wire-format slot -- no clamp (L11). */
411	        for (int i = 0; i < 32; i++)
412	            (void) read_reg_bytes(v->vreg[i],
413	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
414	                                  (size_t) s.vlenb);
415	    }
416	
417	    // v6: which mask-governed CSRs the guest actually wrote (translate-time
418	    // decode + exec callbacks above). ucode rides transport-always: DSP
419	    // instructions update its sticky OV flag without any CSR instruction, so
420	    // instruction-level tracking cannot see those writes (like fcsr's fflags).
421	    s.write_mask[0] = __atomic_load_n(&csr_write_mask[0], __ATOMIC_RELAXED);
422	    s.write_mask[1] = __atomic_load_n(&csr_write_mask[1], __ATOMIC_RELAXED);
423	    hybrid_wm_set(s.write_mask, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_ucode);
424	    s.flags |= HYBRID_FLAG_WRITE_MASK;
425	
426	    // v5: L2C MMIO register window (DS220 11.8.5 Table 112, offsets
427	    // 0x0000..0x0527). Read the whole documented block from the L2C base by
428	    // PHYSICAL address (paging is off in the M-mode boot flow, so VA==PA anyway).
429	    // QEMU's AE350 machine maps L2C as a device region; if the read fails (a
430	    // machine without an L2C), the flag stays clear and consumers skip the
431	    // block. Little-endian native host, so the raw bytes land directly in
432	    // s.l2c.reg[]. The vsim side gates restore on its OWN L2C presence, so
433	    // setting the flag whenever QEMU can read the region is correct.
434	    {
435	        g_autoptr(GByteArray) l2c = g_byte_array_new();
436	        enum qemu_plugin_hwaddr_operation_result r =
437	            qemu_plugin_read_memory_hwaddr(l2c_base_arg, l2c,
438	                                           HYBRID_L2C_REG_WINDOW_BYTES);
439	        if (r == QEMU_PLUGIN_HWADDR_OPERATION_OK
440	            && l2c->len == HYBRID_L2C_REG_WINDOW_BYTES) {
441	            memcpy(s.l2c.reg, l2c->data, HYBRID_L2C_REG_WINDOW_BYTES);
442	            s.flags |= HYBRID_FLAG_L2C;
443	        }
444	    }
445	
446	    *sp = s;
447	}
