449	// LM sidecar drain: read `size` bytes of local memory at physical `base`
450	// (the slave-port aperture) into "<state_path><suffix>". Failure is as hard
451	// an error as a failed state write: the caller asked for this memory
452	// (size > 0), so a missing/short sidecar must not masquerade as a clean
453	// handoff -- the vsim leg would silently resume with an empty ILM/DLM,
454	// exactly the bug this transport exists to fix.
455	static void drain_lm_sidecar(const char *state_path, const char *suffix,
456	                             uint64_t base, uint64_t size)
457	{
458	    if (size == 0) return;
459	    g_autofree char *path = g_strdup_printf("%s%s", state_path, suffix);
460	    g_autoptr(GByteArray) buf = g_byte_array_new();
461	    enum qemu_plugin_hwaddr_operation_result r =
462	        qemu_plugin_read_memory_hwaddr(base, buf, size);
463	    if (r != QEMU_PLUGIN_HWADDR_OPERATION_OK || buf->len != size) {
464	        fprintf(stderr,
465	                "hybrid_handoff: cannot read %" PRIu64 " bytes of local "
466	                "memory at %#" PRIx64 " (result %d)\n", size, base, (int) r);
467	        exit(2);
468	    }
469	    if (write_blob_atomic(buf->data, buf->len, path) != 0) {
470	        fprintf(stderr, "hybrid_handoff: failed to write %s\n", path);
471	        exit(2);
472	    }
473	}
474	
475	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
476	// exit(200).
477	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
478	                                const char *path)
479	{
480	    struct hybrid_state_v1 s;
481	    drain_state_into(vcpu_idx, pc, &s);
482	    if (write_state_atomic(&s, path) != 0) {
483	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
484	        exit(2);
485	    }
486	    // LM transport (F1) + HVM transport (F2): content sidecars ride next to
487	    // the state file; this is the single choke point, so every trigger mode
488	    // (marker/pc/oracle) gets them.
489	    drain_lm_sidecar(path, ".ilm", ilm_base_arg, ilm_size_arg);
490	    drain_lm_sidecar(path, ".dlm", dlm_base_arg, dlm_size_arg);
491	    drain_lm_sidecar(path, ".hvm", hvm_base_arg, hvm_size_arg);
492	    if (log_level_arg <= 1) {
493	        fprintf(stderr,
494	                "[hybrid_handoff] drained state to %s (pc=%#" PRIx64
495	                ", flags=%#x, vlenb=%" PRIu64 ")\n",
496	                path, s.pc, s.flags, (uint64_t) s.vlenb);
497	    }
498	}
