500	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
501	// as the vsim resume point, and exit 200.
502	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
503	{
504	    drain_state_to_file(vcpu_idx, resume_pc, outfile_path);
505	    // 200 == kExitHandoffToQemu in the vsim repo's src/hybrid/exit_codes.hpp.
506	    // Distinguishes drain from workload completion (0) so the orchestrator
507	    // can decide the next spawn.
508	    exit(200);
509	}
510	
511	// Marker sites. The marker is an architectural NOP, so the pre-execution
512	// state equals the post-retire state and the window resumes AFTER it
513	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
514	// the exec callback can lag the actual current insn when V instructions
515	// retire just before the trigger -- TCG defers PC writes for performance).
516	static void on_handoff(unsigned int vcpu_idx, void *udata)
517	{
518	    const HandoffSite *site = (const HandoffSite *) udata;
519	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
520	}
521	
522	// pc boundary sites. Exec callbacks fire BEFORE the insn
523	// executes, and the boundary insn is real user code (unlike a marker NOP):
524	// the drained state must resume AT the boundary so the insn executes inside
525	// the vsim window rather than on neither leg. (Skipping it corrupts the
526	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
527	// set and the first vector op of the window faults.)
528	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
529	{
530	    const HandoffSite *site = (const HandoffSite *) udata;
531	    handoff_drain(vcpu_idx, site->vaddr);
532	}
533	
534	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
535	// When armed (the exit boundary's own tick ran), this tick fires before its
536	// insn executes, so a drain here records the post-retire state of the
537	// boundary insn with pc = the dynamically-next insn's vaddr.
538	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
539	{
540	    const HandoffSite *site = (const HandoffSite *) udata;
541	    if (oracle_armed
542	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
543	        handoff_drain(vcpu_idx, site->vaddr);
544	    }
545	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
546	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
547	        oracle_armed = 1;
548	    }
549	}
550	
551	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
552	{
553	    (void) id;
554	    size_t n = qemu_plugin_tb_n_insns(tb);
555	
556	    for (size_t i = 0; i < n; i++) {
557	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
558	
559	        // v6: CSR write-mask tracking, active in every trigger mode (the mode
560	        // branches below `continue`). Decoded once at translation; only an
561	        // instruction that writes a mask-governed CSR gets an exec callback
562	        // (the CSR address is a static field of the encoding), so this costs
563	        // nothing at execution time outside boot-style CSR setup code. No
564	        // compressed CSR instruction exists, so the size==4 gate is exact.
565	        if (qemu_plugin_insn_size(insn) == 4) {
566	            uint32_t w = 0;
567	            if (qemu_plugin_insn_data(insn, &w, sizeof(w)) == sizeof(w)) {
568	                const int slot = hybrid_wm_slot_for_insn(w);
569	                if (slot >= 0)
570	                    qemu_plugin_register_vcpu_insn_exec_cb(
571	                        insn, on_csr_write, QEMU_PLUGIN_CB_NO_REGS,
572	                        (void *) (uintptr_t) slot);
573	            }
574	        }
575	
576	        // Oracle exit-drain mode: exclusive with every other mode (enforced
577	        // at install), so it owns the insn's registration outright. The site
578	        // carries the marker kind so the tick can arm on the EXIT marker.
579	        if (exit_marker_mode || exit_pc_mode) {
580	            HandoffSite *site = g_new0(HandoffSite, 1);
581	            site->kind  = HYBRID_HANDOFF_NONE;
582	            site->vaddr = qemu_plugin_insn_vaddr(insn);
583	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
584	            if (exit_marker_mode && site->size == 4) {
585	                uint32_t raw = 0;
586	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
587	                    hybrid_match_handoff_insn(raw, &site->kind);
588	            }
589	            qemu_plugin_register_vcpu_insn_exec_cb(
590	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
591	            continue;
592	        }
593	
594	        if (pc_mode) {
595	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
596	            // boundary (on_handoff_boundary), so the insn size is recorded
597	            // only for completeness.
598	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
599	            HandoffSite *site = g_new0(HandoffSite, 1);
600	            site->kind  = HYBRID_HANDOFF_ENTER;
601	            site->vaddr = qemu_plugin_insn_vaddr(insn);
602	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
603	            qemu_plugin_register_vcpu_insn_exec_cb(
604	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
605	            continue;
606	        }
607	
608	        // Marker-trigger mode (default).
609	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
610	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
611	        // exact, not an approximation.
612	        size_t sz = qemu_plugin_insn_size(insn);
613	        if (sz != 4) continue;
614	        uint32_t raw = 0;
615	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
616	            continue;
617	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
618	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
619	        // QEMU1 acts only on the ENTER marker: the drain exit(200)s before
620	        // any EXIT marker can retire (EXIT is vsim's trigger), so an EXIT
621	        // site would only register a permanently no-op exec callback.
622	        if (kind != HYBRID_HANDOFF_ENTER) continue;
623	        HandoffSite *site = g_new0(HandoffSite, 1);
624	        site->kind  = kind;
625	        site->vaddr = qemu_plugin_insn_vaddr(insn);
626	        site->size  = (uint32_t) sz;
627	        qemu_plugin_register_vcpu_insn_exec_cb(
628	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
629	    }
630	}
631	
632	// Parse a `name=value` plugin arg's value as u64 (base auto-detected, so
633	// 0x-hex and decimal both work). Same accept/reject behavior as the previous
634	// per-option copies of this block. Returns 0 on success, -1 (after printing
635	// the standard invalid-arg line) on garbage.
636	static int parse_u64_arg(const char *name, const char *val, uint64_t *out)
637	{
638	    char *endp = NULL;
639	    unsigned long long v = g_ascii_strtoull(val, &endp, 0);
640	    if (!endp || *endp != '\0') {
641	        fprintf(stderr, "hybrid_handoff: invalid %s=%s\n", name, val);
642	        return -1;
643	    }
644	    *out = (uint64_t) v;
645	    return 0;
646	}
647	
648	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
649	                                           const qemu_info_t *info,
650	                                           int argc, char **argv)
651	{
652	    (void) info;
653	    for (int i = 0; i < argc; i++) {
654	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
655	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
656	            outfile_path = g_strdup(tok[1]);
657	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
658	            if (parse_u64_arg("enter_pc", tok[1], &enter_pc_arg) != 0)
659	                return -1;
660	            pc_mode = 1;
661	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
662	            if (parse_u64_arg("exit_pc", tok[1], &exit_pc_arg) != 0)
663	                return -1;
664	            exit_pc_mode = 1;
665	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
666	            uint64_t v;
667	            if (parse_u64_arg("exit_marker", tok[1], &v) != 0)
668	                return -1;
669	            exit_marker_mode = (v != 0);
670	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
671	            if (parse_u64_arg("drain_pc", tok[1], &drain_pc_arg) != 0)
672	                return -1;
673	            drain_pc_set = 1;
674	        } else if (g_strcmp0(tok[0], "l2c_base") == 0 && tok[1]) {
675	            if (parse_u64_arg("l2c_base", tok[1], &l2c_base_arg) != 0)
676	                return -1;
677	        } else if (g_strcmp0(tok[0], "ilm_base") == 0 && tok[1]) {
678	            if (parse_u64_arg("ilm_base", tok[1], &ilm_base_arg) != 0)
679	                return -1;
680	        } else if (g_strcmp0(tok[0], "ilm_size") == 0 && tok[1]) {
681	            if (parse_u64_arg("ilm_size", tok[1], &ilm_size_arg) != 0)
682	                return -1;
683	        } else if (g_strcmp0(tok[0], "dlm_base") == 0 && tok[1]) {
684	            if (parse_u64_arg("dlm_base", tok[1], &dlm_base_arg) != 0)
685	                return -1;
686	        } else if (g_strcmp0(tok[0], "dlm_size") == 0 && tok[1]) {
687	            if (parse_u64_arg("dlm_size", tok[1], &dlm_size_arg) != 0)
688	                return -1;
689	        } else if (g_strcmp0(tok[0], "hvm_base") == 0 && tok[1]) {
690	            if (parse_u64_arg("hvm_base", tok[1], &hvm_base_arg) != 0)
691	                return -1;
692	        } else if (g_strcmp0(tok[0], "hvm_size") == 0 && tok[1]) {
693	            if (parse_u64_arg("hvm_size", tok[1], &hvm_size_arg) != 0)
694	                return -1;
695	        } else if (g_strcmp0(tok[0], "log_level") == 0 && tok[1]) {
696	            if (parse_u64_arg("log_level", tok[1], &log_level_arg) != 0)
697	                return -1;
698	        } else {
699	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
700	            return -1;
701	        }
702	    }
703	    if (!outfile_path) {
704	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
705	        return -1;
706	    }
707	    if (pc_mode) {
708	        fprintf(stderr,
709	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
710	                enter_pc_arg);
711	    }
712	    if (exit_marker_mode || exit_pc_mode) {
713	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
714	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
715	                  "is exclusive with the other trigger modes\n", stderr);
716	            return -1;
717	        }
718	        if (exit_pc_mode) {
719	            fprintf(stderr,
720	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
721	                    PRIx64 "\n", exit_pc_arg);
722	        } else {
723	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
724	                  stderr);
725	        }
726	        if (drain_pc_set) {
727	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
728	                    drain_pc_arg);
729	        }
730	    } else if (drain_pc_set) {
731	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
732	              "(exit_marker/exit_pc)\n", stderr);
733	        return -1;
734	    }
735	
736	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
737	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
738	    return 0;
739	}
