20	// Strip one trailing '\r' (the cfg may come from a CRLF-writing engine) and
21	// surrounding spaces/tabs.
22	std::string trim(const std::string& s) {
23	  size_t b = s.find_first_not_of(" \t\r");
24	  if (b == std::string::npos) return "";
25	  size_t e = s.find_last_not_of(" \t\r");
26	  return s.substr(b, e - b + 1);
