29	// `key = "value"` -> value (quotes optional); "" when the line is not `key = ...`.
30	std::string ini_value(const std::string& line, const char* key) {
31	  const std::string t = trim(line);
32	  const std::string pfx = std::string(key);
33	  if (t.compare(0, pfx.size(), pfx) != 0) return "";
34	  size_t i = pfx.size();
35	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
36	  if (i >= t.size() || t[i] != '=') return "";
37	  ++i;
38	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
39	  std::string v = t.substr(i);
40	  if (v.size() >= 2 && v.front() == '"' && v.back() == '"')
41	    v = v.substr(1, v.size() - 2);
42	  return v;
43	}
